/**
 * Writes assets/LICENSES.json rows for every file in public/art (the licence choke point, tests/unit/licenses.test.ts).
 * The painted art is generated by the studio and dedicated CC0. Models used (all free, no account, no money):
 *   FLUX.1 [schnell] (Apache-2.0) on a public Hugging Face Space · Juggernaut XL (SDXL, CreativeML Open RAIL++-M) on the AI Horde ·
 *   cut-outs by BiRefNet-lite (MIT) run locally.
 */
import fs from 'node:fs';

const FLUX = new Set(
  JSON.parse(
    fs.existsSync('assets/art-src/flux.json')
      ? fs.readFileSync('assets/art-src/flux.json', 'utf8')
      : '["key"]',
  ),
);
const m = JSON.parse(fs.readFileSync('assets/LICENSES.json', 'utf8'));
m.note =
  'Every shipped file must be listed here (tests/unit/licenses.test.ts). Allowed: CC0-1.0, CC-BY-4.0 (CC-BY needs the credits screen).';
m.files = {};
for (const f of fs.readdirSync('public/art').sort()) {
  const id = f.replace(/\.webp$/, '');
  m.files[`public/art/${f}`] = {
    pack: 'JUNGLEE painted art (v7)',
    author: 'JUNGLEE studio — generated, then picked and cut out by hand',
    license: 'CC0-1.0',
    source: 'https://github.com/SHV27/junglee',
    modified: FLUX.has(id)
      ? 'generated with FLUX.1 [schnell] (Apache-2.0); prompts and seeds in scripts/gen-art.mjs'
      : 'generated with Juggernaut XL (CreativeML Open RAIL++-M) on the AI Horde; cut out with BiRefNet-lite (MIT); prompts and seeds in scripts/gen-art.mjs',
  };
}
fs.writeFileSync('assets/LICENSES.json', `${JSON.stringify(m, null, 2)}\n`);
console.log(Object.keys(m.files).length, 'rows');
